internal class GUPPriceEnginePriceDiscoveryEngine
{
    private GUPPriceEnginePrematchObject prematchObject;
    private List matchedJournalLineList;
    private List allChosenLines;
    private real matchedJournalLowestPrice;
    private real marginCodePrice;
    private real marginCodeBasePrice;

}

Method.Source:
public void new(GUPPriceEnginePrematchObject _prematchObject)
{
    this.prematchObject = _prematchObject;
    this.refreshEngine();
}

public real parmMarginCodePrice()
{
    return this.marginCodePrice;
}

    public GUPPriceEngineDecoratedPriceLine findTradeAgreementBasePrice()
    {
        this.refreshEngine();

        this.matchTradeAgreementJournalLines();
        GUPPriceEngineDecoratedPriceLine ret = this.getBestPriceFromMatchedList();

        return ret;
    }

    public List findAppliedMarginAdjustment(real _basePrice)
    {
        this.refreshEngine();

        List marginComponentList = prematchObject.parmMarginComponentList();
        List ret;

        if (marginComponentList)
        {
            ListEnumerator marginAdjustmentAggrListEnum = marginComponentList.getEnumerator();
            GUPPriceEngineMarginComponent currentMarginCode;

            marginCodePrice = _basePrice;
            marginCodeBasePrice = _basePrice;

            //loop among margin codes
            while (marginAdjustmentAggrListEnum.moveNext())
            {
                GUPPriceEngineMarginComponent marginComponent = marginAdjustmentAggrListEnum.current();
                this.calculateSingleMarginCode(marginComponent);

                matchedJournalLineList = new List(Types::Class);
                matchedJournalLowestPrice = 0;
            }
        }

        ret = allChosenLines;
        return ret;
    }

public void refreshEngine()
{
    allChosenLines = new List(Types::Class);
    matchedJournalLineList = new List(Types::Class);
    matchedJournalLowestPrice = realMax();
    marginCodePrice = 0;
}

    private void calculateSingleMarginCode(GUPPriceEngineMarginComponent _marginComponent)
    {
        GUPPriceEngineMarginCodeLineAggregation previousMarginCodeLineAggr;
        GUPPriceEngineMarginCodeLineAggregation marginCodeLineAggr;
        ListEnumerator marginCodeLineAggrListEnum;

        // first find from fixed list
        List fixedAmountAggrList = _marginComponent.parmFixedAmountAggregationList();
        if (fixedAmountAggrList)
        {
            marginCodeLineAggrListEnum = fixedAmountAggrList.getEnumerator();

            while (marginCodeLineAggrListEnum.moveNext())
            {
                marginCodeLineAggr = marginCodeLineAggrListEnum.current();

                if (previousMarginCodeLineAggr && matchedJournalLowestPrice && this.marginCodeFixedAmountTerminateNow(previousMarginCodeLineAggr, marginCodeLineAggr))
                {
                    break;
                }

                if (this.matchMarginCodeLineAggr(marginCodeLineAggr))
                {
                    previousMarginCodeLineAggr = marginCodeLineAggr;
                }
            }
        }
        
        // then find from percent list
        List percentAggrList = _marginComponent.parmPercentageAggregationList();
        if (percentAggrList)
        {
            marginCodeLineAggrListEnum = percentAggrList.getEnumerator();

            while (marginCodeLineAggrListEnum.moveNext())
            {
                marginCodeLineAggr = marginCodeLineAggrListEnum.current();

                if (previousMarginCodeLineAggr && matchedJournalLowestPrice && this.marginCodePercentTerminateNow(previousMarginCodeLineAggr, marginCodeLineAggr))
                {
                    break;
                }

                if (this.matchMarginCodeLineAggr(marginCodeLineAggr))
                {
                    previousMarginCodeLineAggr = marginCodeLineAggr;
                }
            }
        }
        
        GUPPriceEngineDecoratedAdjustmentValueLine chosenLine = this.findMatchedLineWithLowestComputedPrice();

        if (chosenLine)
        {
            marginCodePrice = marginCodePrice + chosenLine.parmComputedPrice();
            allChosenLines.addEnd(chosenLine);
        }
    }

    //todo: could be a GUPIComparator
    private GUPPriceEngineDecoratedAdjustmentValueLine findMatchedLineWithLowestComputedPrice()
    {
        GUPPriceEngineDecoratedAdjustmentValueLine ret;
        ListEnumerator enum = matchedJournalLineList.getEnumerator();

        ret = this.getBestPriceFromMatchedList();

        return ret;
    }

    private boolean matchMarginCodeLineAggr(GUPPriceEngineMarginCodeLineAggregation _marginCodeLineAggr)
    {
        if (_marginCodeLineAggr.parmIsComputed())
        {
            return true;
        }

        boolean matched;
        List matchedAdjustmentValueLine = new List(Types::Class);


        // first find from fixed list inside of single line aggregation(competing lines)
        if (_marginCodeLineAggr.parmFixedAmountListLength())
        {
            ListEnumerator fixedAmountLineListEnum = _marginCodeLineAggr.parmFixedAmountLineList().getEnumerator();
            GUPPriceEngineDecoratedAdjustmentValueLine fixedAmountDecoratedLine;

            //todo: some logic here can be extracted to a common method
            while (fixedAmountLineListEnum.moveNext())
            {
                fixedAmountDecoratedLine = fixedAmountLineListEnum.current();
                GUPPriceEngineMarginCodeLine journalLine = fixedAmountDecoratedLine.parmJournalLine();
                matched = this.matchSingleJournalLineWithSingleMap(prematchObject.parmSalesTableRelatedDataMap(), journalLine.parmHeaderAttribute())
                && this.matchSingleJournalLineWithSingleMap(prematchObject.parmSalesLineRelatedDataMap(), journalLine.parmLineAttribute());
            
                if (matched)
                {
                    fixedAmountDecoratedLine.parmComputedPrice(true, fixedAmountDecoratedLine.parmAdjustmentValue());
                    matchedAdjustmentValueLine.addEnd(fixedAmountDecoratedLine);
                    break;
                }
            }
        }

        //then find from percent list inside of single line aggregation(competing lines)
        if (_marginCodeLineAggr.parmPercentListLength())
        {
            ListEnumerator percentLineListEnum = _marginCodeLineAggr.parmPercentLineList().getEnumerator();
            GUPPriceEngineDecoratedAdjustmentValueLine percentDecoratedLine;
            Price basePrice;

            while (percentLineListEnum.moveNext())
            {
                percentDecoratedLine = percentLineListEnum.current();
                GUPPriceEngineMarginCodeLine journalLine = percentDecoratedLine.parmJournalLine();
                matched = this.matchSingleJournalLineWithSingleMap(prematchObject.parmSalesTableRelatedDataMap(), journalLine.parmHeaderAttribute())
                && this.matchSingleJournalLineWithSingleMap(prematchObject.parmSalesLineRelatedDataMap(), journalLine.parmLineAttribute());

                if (matched)
                {
                    basePrice = journalLine.parmComponentSetup().CompoundcalculationBasis ? marginCodePrice : marginCodeBasePrice;
                    percentDecoratedLine.parmComputedPrice(true, percentDecoratedLine.parmAdjustmentValue() / 100 * basePrice);
                    matchedAdjustmentValueLine.addEnd(percentDecoratedLine);
                    break;
                }
            }
        }

        GUPPriceEngineDecoratedAdjustmentValueLine bestLine = this.retrieveBestLineFromList(matchedAdjustmentValueLine);
        real bestAdjustmentAmount = bestLine.parmComputedPrice();

        if (bestAdjustmentAmount)
        {
            bestLine.parmJournalLine().parmAggrLinePriority(true, _marginCodeLineAggr.parmLinePriority());
            matchedJournalLineList.addEnd(bestLine);
            matchedJournalLowestPrice = matchedJournalLowestPrice < bestAdjustmentAmount ? matchedJournalLowestPrice : bestAdjustmentAmount;
            _marginCodeLineAggr.parmComputedPrice(bestAdjustmentAmount);
            _marginCodeLineAggr.parmIsComputed(true);

            return true;
        }

        return false;
    }

    private GUPPriceEngineDecoratedAdjustmentValueLine retrieveBestLineFromList(List _matchedAdjustmentValueLine)
    {
        GUPPriceEngineDecoratedAdjustmentValueLine line1;
        GUPPriceEngineDecoratedAdjustmentValueLine line2;
        GUPPriceEngineDecoratedAdjustmentValueLine ret;

        if (_matchedAdjustmentValueLine)
        {
            ListEnumerator enum = _matchedAdjustmentValueLine.getEnumerator();

            //_matchedAdjustmentValueLine should only have 0, 1 or 2 elements.
            switch (_matchedAdjustmentValueLine.elements())
            {
                case 0:
                    break;

                case 1:
                    enum.moveNext();
                    ret = enum.current();
                    break;
            
                case 2:
                    enum.moveNext();
                    line1 = enum.current();
                    enum.moveNext();
                    line2 = enum.current();
                    if (this.comparePriority(line1, line2) < 0 ||
                    (this.comparePriority(line1, line2) == 0 && line1.parmComputedPrice() < line2.parmComputedPrice()))
                    {
                        _matchedAdjustmentValueLine = new List(Types::Class);
                        _matchedAdjustmentValueLine.addEnd(line1);
                        ret = line1;
                    }
                    else
                    {
                        _matchedAdjustmentValueLine = new List(Types::Class);
                        _matchedAdjustmentValueLine.addEnd(line2);
                        ret = line2;
                    }
                    break;

                default:
            }
        }

        return ret;
    }

    //todo: could be a GUPIComparator
    private int comparePriority(GUPPriceEngineDecoratedAdjustmentValueLine _obj1, GUPPriceEngineDecoratedAdjustmentValueLine _obj2)
    {
        Array priority1 = _obj1.parmAttributesPriority();
        Array priority2 = _obj2.parmAttributesPriority();

        // Line with less attributes is considered 'smaller'.
        if (priority1.lastIndex() != priority2.lastIndex())
        {
            return priority1.lastIndex() - priority2.lastIndex();
        }
        
        // Sort by attribute priority in descending order (most specific to most general).
        // In each attribute, larger value is preferred (0 = ALL, 1 = Specific, 1+ = different level in attribute 'Category')
        for (int i = 1; i <= priority1.lastIndex(); i++)
        {
            if (priority1.value(i) != priority2.value(i))
            {
                return priority2.value(i) - priority1.value(i);
            }
        }

        return 0;
    }

    private GUPPriceEngineAbstractDecoratedLine getBestPriceFromMatchedList()
    {
        GUPPriceEngineAbstractDecoratedLine ret;
        GUPListSorter listSorter = GUPListSorter::getInstance();
        GUPComparatorMatchedJournalLineObject journalComparator = new GUPComparatorMatchedJournalLineObject();
        matchedJournalLineList = listSorter.sortList(matchedJournalLineList, journalComparator);

        ListEnumerator enum = matchedJournalLineList.getEnumerator();
        if (enum.moveNext())
        {
            ret = enum.current();
        }
        return ret;
    }

    private void matchTradeAgreementJournalLines()
    {
        List tamJournalLineList = prematchObject.parmTradeAgreementJournalLineList();

        if (tamJournalLineList)
        {
            ListEnumerator tamJournalLineAggrListEnum = tamJournalLineList.getEnumerator();
            GUPPriceEngineTradeAgreementLineAggregation previousAggrObject;
            GUPPriceEngineTradeAgreementLineAggregation currentAggrObject;

            while (tamJournalLineAggrListEnum.moveNext())
            {
                currentAggrObject = tamJournalLineAggrListEnum.current();

                if (previousAggrObject && matchedJournalLowestPrice && this.terminateNow(previousAggrObject, currentAggrObject))
                {
                    return;
                }

                boolean matched = this.matchSingleJournalLineAggr(prematchObject.parmSalesTableRelatedDataMap(),
                prematchObject.parmSalesLineRelatedDataMap(),
                currentAggrObject);

                if (matched)
                {
                    previousAggrObject = currentAggrObject;
                }
            }
        }
    }

    private boolean terminateNow(GUPPriceEngineTradeAgreementLineAggregation _previousAggrObject, GUPPriceEngineTradeAgreementLineAggregation _currentAggrObject)
    {
        boolean ret = false;

        // For find next (ignore priority) search, all aggregation has priority = 0, and each aggregation contains exactly one line.
        if ((_currentAggrObject.parmLinePriority() == _previousAggrObject.parmLinePriority() && _currentAggrObject.parmLowestPrice() >= this.matchedJournalLowestPrice) ||
            _currentAggrObject.parmLinePriority() < _previousAggrObject.parmLinePriority())
        {
            ret = true;
        }

        return ret;
    }

    private boolean marginCodeFixedAmountTerminateNow(GUPPriceEngineMarginCodeLineAggregation _previousAggrObject, GUPPriceEngineMarginCodeLineAggregation _currentAggrObject)
    {
        boolean ret = false;

        if ((_currentAggrObject.parmLinePriority() == _previousAggrObject.parmLinePriority() && _currentAggrObject.parmLowestFixedAmount() >= this.matchedJournalLowestPrice) ||
            _currentAggrObject.parmLinePriority() < _previousAggrObject.parmLinePriority())
        {
            ret = true;
        }

        return ret;
    }

    private boolean marginCodePercentTerminateNow(GUPPriceEngineMarginCodeLineAggregation _previousAggrObject, GUPPriceEngineMarginCodeLineAggregation _currentAggrObject)
    {
        boolean ret = false;

        if ((_currentAggrObject.parmLinePriority() == _previousAggrObject.parmLinePriority() && _currentAggrObject.parmLowestPercentage() * marginCodePrice >= this.matchedJournalLowestPrice) ||
            _currentAggrObject.parmLinePriority() < _previousAggrObject.parmLinePriority())
        {
            ret = true;
        }

        return ret;
    }

    private boolean matchSingleJournalLineAggr(
        Map _salesTableRelatedDataMap,
        Map _salesLineRelatedDataMap,
        GUPPriceEngineTradeAgreementLineAggregation _tamJournalLineObject)
    {
        boolean matched = true;
        List journalLineList = _tamJournalLineObject.parmLineList();

        if (journalLineList)
        {
            ListEnumerator tamJournalLineListEnum = journalLineList.getEnumerator();
            GUPPriceEngineDecoratedPriceLine journalLine;
            GUPPriceEngineTradeAgreementLine tamJournalLineObject;

            while (tamJournalLineListEnum.moveNext())
            {
                journalLine = tamJournalLineListEnum.current();
                tamJournalLineObject = journalLine.parmJournalLine();
                matched = this.matchSingleJournalLineWithSingleMap(_salesTableRelatedDataMap, tamJournalLineObject.parmHeaderAttribute())
                && this.matchSingleJournalLineWithSingleMap(_salesLineRelatedDataMap, tamJournalLineObject.parmLineAttribute());
                if (matched)
                {
                    this.addMatchedJournalLine(journalLine, _tamJournalLineObject);
                    break;
                }
            }
        }

        return matched;
    }

private void addMatchedJournalLine(GUPPriceEngineDecoratedPriceLine _journalLine, GUPPriceEngineTradeAgreementLineAggregation _tamJournalLineObject)
{
    _journalLine.parmJournalLine().parmAggrLinePriority(true, _tamJournalLineObject.parmLinePriority());
    matchedJournalLineList.addEnd(_journalLine);
    real journalLineLowestPrice = _journalLine.parmPrice();
    matchedJournalLowestPrice = matchedJournalLowestPrice == 0 ? journalLineLowestPrice : (journalLineLowestPrice < matchedJournalLowestPrice ? journalLineLowestPrice : matchedJournalLowestPrice);
}

    private boolean matchSingleJournalLineWithSingleMap(Map _dataMap, GUPPriceEngineAttributeGroupObject _tamAttributeGroupObject)
    {
        boolean matched = true;

        // When attributegroup = all, this list is null.
        if (_tamAttributeGroupObject)
        {
            List attributeConditionValueList = _tamAttributeGroupObject.parmAttributeConditionValueList();

            if (attributeConditionValueList)
            {
                // TODO: add logic here to compare dataMap with tamJournalLineObject
                ListEnumerator attrConditionValueListEnum = _tamAttributeGroupObject.parmAttributeConditionValueList().getEnumerator();

                while (attrConditionValueListEnum.moveNext())
                {
                    GUPPriceEngineConditionValueObject conditionValueObject = attrConditionValueListEnum.current();

                    if (!this.matchSingleAttributeValue(_dataMap, conditionValueObject))
                    {
                        matched = false;
                        break;
                    }
                }
            }
        }

        return matched;
    }

    private boolean matchSingleAttributeValue(Map _dataMap, GUPPriceEngineConditionValueObject _conditionValueObject)
    {
        GUPIPricingAttribute pricingAttribute = _conditionValueObject.parmPricingAttribute();
        str datasourceIdentifier = pricingAttribute.getQueryBuilderDatasourceIdentifier();
        str attrValue;
        str condValue = _conditionValueObject.parmConditionValue();
        boolean matched = true;

        if (_dataMap.exists(datasourceIdentifier))
        {
            GUPPriceEngineRelatedDataObject dataObject = _dataMap.lookup(datasourceIdentifier);
            if (dataObject.isEcoResAttribute())
            {
                GUPPricingAttributeEcoResAttribute ecoResAttribute = pricingAttribute as GUPPricingAttributeEcoResAttribute;
                attrValue = dataObject.getValueByEcoResAttributeKey(ecoResAttribute.getName(), ecoResAttribute.getAttributeType());
            }
            else
            {
                DictClass dc = new DictClass(classIdGet(pricingAttribute));
                GUPPricingAttributeFieldsDiscoveryAttribute attribute = (dc.getAttribute('GUPPricingAttributeFieldsDiscoveryAttribute') as GUPPricingAttributeFieldsDiscoveryAttribute);
                str fieldName = attribute.parmFieldName();
                attrValue = dataObject.parmData().getFieldValue(fieldName);
            }
            if (!this.matchValue(attrValue, condValue, this.isCategoryHierarchy(_conditionValueObject)))
            {
                matched = false;
            }
        }
        else
        {
            error(strFmt('datasourceIdentifier %1 not found in data map', datasourceIdentifier));
        }

        return matched;
    }

private boolean isCategoryHierarchy(GUPPriceEngineConditionValueObject _conditionValueObject)
{
    return _conditionValueObject.parmAttributeLink().PriceAttributeClassId == classNum(GUPPricingAttributeEcoResProductCategoryCategory);
}

    private boolean matchValue(str _attrValue, str _condValue, boolean _isCategoryHierarchy)
    {
        GUPMultipleValueMatchingProcessor matchingProcessor = new GUPMultipleValueMatchingProcessor();
        boolean ret;

        if (_isCategoryHierarchy)
        {
            ret = matchingProcessor.hierarchyValueEqual(_attrValue, _condValue);
        }
        else
        {
            ret = matchingProcessor.valueEqual(_attrValue, _condValue);
        }

        return ret;
    }
